cssCode:
#container { display: flex; justify-content: center; align-items: center; background: #000; position: relative; }
.spotlight-text-base {
  font-family: sans-serif; font-size: 80px; font-weight: 900;
  color: #1a1a1a; /* ડાર્ક ગ્રે કલર, જે બેકગ્રાઉન્ડમાં છુપાયેલો લાગશે */
  position: relative; text-transform: uppercase; letter-spacing: 5px;
}
.spotlight-text-overlay {
  position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  font-family: sans-serif; font-size: 80px; font-weight: 900;
  text-transform: uppercase; letter-spacing: 5px;
  background: linear-gradient(90deg, #00ffcc, #ff007f, #00d2ff);
  background-size: 200%; animation: bgFlow 3s linear infinite;
  -webkit-background-clip: text; color: transparent;
  /* જાદુ અહીં છે: ક્લિપ પાથ */
  clip-path: circle(0px at var(--x, 50%) var(--y, 50%));
  transition: clip-path 0.1s ease-out; pointer-events: none;
}
@keyframes bgFlow { 0% { background-position: 0% 50%; } 100% { background-position: 100% 50%; } }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;justify-content:center;align-items:center;background:#000;position:relative;';

const baseText = document.createElement('div');
baseText.className = 'spotlight-text-base';
baseText.innerText = 'MAGIC';

const overlayText = document.createElement('div');
overlayText.className = 'spotlight-text-overlay';
overlayText.innerText = 'MAGIC';

baseText.appendChild(overlayText);
c.appendChild(baseText);

c.addEventListener('pointermove', (e) => {
  const rect = baseText.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;

  // આંગળીની આસપાસ 80px ની ત્રિજ્યામાં જ કલરફુલ ટેક્સ્ટ દેખાશે
  overlayText.style.clipPath = `circle(80px at ${x}px ${y}px)`;
});

c.addEventListener('pointerleave', () => {
  // આંગળી હટાવતા જ સ્પોટલાઈટ ઝીરો થઈ જશે
  overlayText.style.clipPath = `circle(0px at 50% 50%)`;
});
